result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/printcss/test/print.test.js", "content": "import { describe, it, expect } from 'vitest';
import postcss from 'postcss';
import { printStyles } from '../src/print.js';

/** Parse generated CSS once per test via helper. */
const parse = (options) => postcss.parse(printStyles(options));

describe('printStyles', () => {
  it('emits exactly one @media print block and one @page rule and nothing else', () => {
    const root = parse({ hide: ['.sidebar'] });

    const topLevel = root.nodes;
    expect(topLevel).toHaveLength(3); // media block + empty text node(s) tolerated as raws

    const nonAtRules = topLevel.filter(
      (n) => n.type === 'rule'
    );
    expect(nonAtRules).toEqual([]); // no top-level style rules leak

    const medias = root.nodes.filter(
      (n) => n.type === 'atrule' && n.name === 'media'
    );
    expect(medias).toHaveLength(1);
    expect(medias[0].params).toBe('print');

    const pages = root.nodes.filter(
      (n) => n.type === 'atrule' && n.name === 'page'
    );
    expect(pages).toHaveLength(1);
  });

  it('every style rule lives under the @media print block', () => {
    const root = parse({
      hide: ['.nav', '#cookie-banner', '.ads'],
    });

    const allRules = [];
    root.walkRules((rule) => allRules.push(rule));

    expect(allRules.length).toBeGreaterThan(0);

    for (const rule of allRules) {
      let parent = rule.parent;
      while (parent && !(parent.type === 'atrule' && parent.name === 'media')) {
        parent = parent.parent;
      }
      expect(parent, `rule ${rule.selector} must be inside @media print`).not.toBeNull();
    }
  });

  it('forces white backgrounds and black text', () => {
    const root = parse({});
    const mediaBlock = root.nodes.find(
      (n) => n.type === 'atrule' && n.name === 'media'
    );

    const decls = new Map();
    mediaBlock.walkDecls(({ prop, value }) => decls.set(prop, value));

    // body rule explicitly sets them; universal rule forces them everywhere
    const bodyRule = mediaBlock.nodes.find(
      (n) => n.type === 'rule' && n.selector === 'body'
    );
    expect(bodyRule).toBeDefined();

    const bgDecls = [];
    mediaBlock.walkDecls('background-color', (d) => bgDecls.push(d));
    expect(bgDecls.some((d) => d.value === '#ffffff')).toBe(true);

    const colorDecls = [];
    mediaBlock.walkDecls('color', (d) => colorDecls.push(d));
    expect(colorDecls.every((d) => d.value.includes('#000000'))).toBe(true);
  });

  it('appends href after external links', () => {
    const root = parse({});
    root.walkRules('a[href^="http"]:after', (rule) => {
      const content = rule.nodes.find((d) => d.prop === 'content');
      expect(content).toBeDefined();
      expect(content.value).toBe('attr(href)');
    });
  });

  it('avoids page breaks inside pre and table', () => {
    const root = parse({});
    const breakers = ['pre', 'table'];

    for (const sel of breakers) {
      const rule = root.nodes.find(
        (n) =>
          n.type === 'atrule' &&
          n.name === 'media' &&
          n.nodes.some(
            (r) =>
              r.type === 'rule' &&
              r.selectors &&
              r.selectors.includes(sel)
          )
      );
      expect(rule, `no rule for ${sel}`).toBeDefined();
      const target = rule.nodes.find((r) => r.selectors.includes(sel));
      const bi = target.nodes.find((d) => d.prop === 'break-inside');
      expect(bi, `${sel} missing break-inside`).toBeDefined();
      expect(bi.value).toBe('avoid');
    }
  });

  it('sets sensible page margins via @page rule', () => {
    const root = parse({});
    const page = root.nodes.find(
      (n) => n.type === 'atrule' && n.name === 'page'
    );
    expect(page).toBeDefined();

    const margin = page.nodes.find((d) => d.prop === 'margin');
    expect(margin).toBeDefined();

    // "sensible" = a real length value, not zero or inherit
    expect(margin.value).toMatch(/^\d+(\.\d+)?(cm|mm|in|pt|pc|px)$/);
    const numeric = parseFloat(margin.value);
    expect(numeric).toBeGreaterThan(0);
    expect(numeric).toBeLessThanOrEqual(25.4 * 0.5); // no more than half an inch-ish
  });

  it('hides each configured selector with display none', () => {
    const selectors = ['.sidebar', 'header.site-header', '#cookie-banner'];
    const root = parse({ hide: selectors });
    const mediaBlock = root.first;

    for (const sel of selectors) {
      const rule = mediaBlock.nodes.find(
        (n) => n.type === 'rule' && n.selectors.includes(sel)
      );
      expect(rule, `selector ${sel} not hidden`).toBeDefined();
      const display = rule.nodes.find((d) => d.prop === 'display');
      expect(display, `${sel} missing display`).toBeDefined();
      expect(display.value).toBe('none');
    }
  });

  it('handles missing/empty hide option gracefully', () => {
    for (const options of [{}, { hide: [] }, { hide: undefined }]) {
      const css = printStyles(options);
      const root = postcss.parse(css);
      root.walkRules((rule) => {
        expect(rule.nodes.some((d) => d.prop === 'display' && d.value === 'none')).toBe(false);
      });
    }
  });

  it('never emits any rule outside @media print except @page', () => {
    const root = parse({
      hide: ['.a', '.b'],
    });

    root.each((node) => {
      if (node.type !== 'atrule') return;
      if (node.name === 'page') return; // page rule lives at top level by design
      if (node.name === 'media') {
        expect(node.params).toBe('print');
        return;
      }
      throw new Error(`unexpected top-level @${node.name}`);
    });

    // and there is genuinely nothing that isn't an atrule
    root.each((node) => {
      expect(node.type).toBe('atrule');
    });
  });

  it('output is deterministic for identical input', () => {
    const opts = { hide: ['.x'] };
    expect(printStyles(opts)).toBe(printStyles(opts));
  });
});
"})
